14	func TestShouldSkipDriftWarning(t *testing.T) {
15		t.Parallel()
16	
17		visible := &cobra.Command{Use: "rewind"}
18		hidden := &cobra.Command{Use: "hooks", Hidden: true}
19		hiddenChild := &cobra.Command{Use: "claude-code"}
20		hidden.AddCommand(hiddenChild)
21		enable := &cobra.Command{Use: "enable"}
22		configure := &cobra.Command{Use: "configure"}
23	
24		cases := []struct {
25			name string
26			cmd  *cobra.Command
27			want bool
28		}{
29			{"nil", nil, true},
30			{"visible", visible, false},
31			{"hidden", hidden, true},
32			{"hidden-ancestor", hiddenChild, true},
33			{"enable", enable, false},
34			{"configure", configure, false},
35			{"status", &cobra.Command{Use: "status"}, true},
36		}
37		for _, tc := range cases {
38			t.Run(tc.name, func(t *testing.T) {
39				t.Parallel()
40				if got := shouldSkipDriftWarning(tc.cmd); got != tc.want {
41					t.Errorf("shouldSkipDriftWarning(%q) = %v, want %v", tc.name, got, tc.want)
42				}
43			})
44		}
45	}
46	
47	func TestEmitStaleHooksWarning(t *testing.T) {
48		t.Parallel()
49	
50		t.Run("empty reports writes nothing", func(t *testing.T) {
51			t.Parallel()
52			var buf bytes.Buffer
53			emitStaleHooksWarning(&buf, nil)
54			if buf.Len() != 0 {
55				t.Fatalf("expected no output for empty drifts, got %q", buf.String())
56			}
57		})
58	
59		t.Run("single agent", func(t *testing.T) {
60			t.Parallel()
61			var buf bytes.Buffer
