	run := func(c *cobra.Command) string {
		var buf bytes.Buffer
		c.SetErr(&buf)
		c.SetContext(t.Context())
		driftWarningPreRun(c, nil)
		return buf.String()
	}
	// withTTY flips isTerminalWriterFn to true for the calling subtest only.
	withTTY := func(t *testing.T) {
		t.Helper()
